public class CloudFoundryApplicationFactoryTest {

    @Test
    public void should_use_application_uri() {
        InstanceProperties instanceProperties = new InstanceProperties();
        instanceProperties.setName("test");
        ServerProperties server = new ServerProperties();
        ManagementServerProperties management = new ManagementServerProperties();
        WebEndpointProperties webEndpoint = new WebEndpointProperties();
        CloudFoundryApplicationProperties cfApplicationProperties = new CloudFoundryApplicationProperties();
        // === MOCK-STUB-START ===
        // === MOCK-STUB-END ===
        CloudFoundryApplicationFactory factory = new CloudFoundryApplicationFactory(instanceProperties, management,
            server, pathMappedEndpoints, webEndpoint, () -> singletonMap("contributor", "test"), cfApplicationProperties);
        cfApplicationProperties.setUris(singletonList("application/Uppercase"));

        Application app = factory.createApplication();

        assertEquals("http://application/Uppercase/actuator", app.getManagementUrl());
        assertEquals("http://application/Uppercase/actuator/health", app.getHealthUrl());
        assertEquals("http://application/Uppercase/", app.getServiceUrl());
        assertEquals("test", app.getName());
        assertEquals("test", app.getMetadata().get("contributor"));
        // === VERIFY-START ===
        // === VERIFY-END ===
    }

}

